

# cleanup
rm -rf obj_dir
rm -f counter.vcd


# run Verilator to translate Verilog into C++, including C++ testbench
verilator -Wall --cc --trace --top-module sigdelay sigdelay.sv ram.sv --exe sigdelay_tb.cpp

# build C++ project via make automatically generated by Verilator
make -j -C obj_dir/ -f Vsigdelay.mk Vsigdelay

cp vbuddy.cfg obj_dir
cp vbuddy.cpp obj_dir

# run executable file simulation
obj_dir/Vsigdelay